package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var SchedRecCurrent SchedRec

var schedFile *os.File
var schedReader *bufio.Reader
var schedEOF bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep only low-order digits that fit: modulo 10^(intDigits+scale)
	// v is already at given scale (rounded/truncated)
	totalDigits := intDigits + int(scale)
	mod := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	scaled := v.Shift(scale).Truncate(0)
	// for unsigned values
	if scaled.IsNegative() {
		// keep low order for negative: COBOL would keep sign? ignore, just mod abs then reapply
		neg := scaled.IsNegative()
		absScaled := scaled.Abs()
		rem := absScaled.Mod(mod)
		if neg {
			rem = rem.Neg()
		}
		return rem.Shift(-scale)
	}
	rem := scaled.Mod(mod)
	return rem.Shift(-scale)
}

func formatBalEd(d decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  len 13
	// ensure d is already stored correctly; handle high-order truncation
	// compute integer and decimal parts from cents
	// use store semantics already applied, but also handle overflow here
	intDigits := 8
	scale := int32(2)
	// ensure fit (high-order truncation)
	d = storeDecimal(d, intDigits, scale)
	abs := d.Abs()
	scaled := abs.Shift(scale).Truncate(0)
	// scaled is cents 0 .. 10^10-1
	// use IntPart via IntPart() - may overflow int64 but max 10^10 fits
	cents := scaled.IntPart()
	if cents < 0 {
		cents = -cents
	}
	intPart := cents / 100
	decPart := cents % 100

	integerStr := fmt.Sprintf("%08d", intPart) // 8 digits
	// picture for integer part: "ZZ,ZZZ,ZZ9"
	pic := []rune{'Z', 'Z', ',', 'Z', 'Z', 'Z', ',', 'Z', 'Z', '9'}
	var out []rune
	digitIdx := 0
	suppress := true
	for _, ch := range pic {
		if ch == ',' {
			if suppress {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		} else if ch == 'Z' {
			d := rune(integerStr[digitIdx])
			digitIdx++
			if suppress && d == '0' {
				out = append(out, ' ')
				// suppress stays true
			} else {
				suppress = false
				out = append(out, d)
			}
		} else if ch == '9' {
			d := rune(integerStr[digitIdx])
			digitIdx++
			suppress = false
			out = append(out, d)
		}
	}
	// decimal point and cents
	out = append(out, '.')
	out = append(out, rune('0'+(decPart/10)%10))
	out = append(out, rune('0'+decPart%10))
	return string(out)
}

func formatPIC99(v int64) string {
	// keep low-order 2 digits, zero padded
	mod := v % 100
	if mod < 0 {
		mod += 100
	}
	return fmt.Sprintf("%02d", mod)
}

func parseDigitsField(s string) int64 {
	// s contains digits and possibly spaces; spaces treated as 0
	var n int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			// COBOL numeric field with spaces? treat as 0
			n = n * 10
		}
	}
	return n
}

func READ_PARA() {
	if schedReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := schedReader.ReadString('\n')
	if err != nil && err != io.EOF {
		// treat as EOF?
	}
	if err == io.EOF {
		// line may contain last line without newline
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// otherwise process this line, next call will be EOF
		// trim trailing \r\n already not present except \n
	} else {
		// remove trailing \n and \r
		line = strings.TrimRight(line, "\r\n")
	}
	// If EOF after reading, next call will detect, but we still process this line
	// Detect empty due to EOF? Already handled.
	// Pad with spaces on right if shorter than 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	} else if len(line) > 16 {
		line = line[:16]
	}
	// If we got EOF and line was empty, already returned; otherwise check if line is actually EOF marker?
	// For io.EOF case with data, we will set a flag to return EOF next time after this record
	// Need to know if this was the last line: we consumed it, next read will be EOF
	// To handle, we can peek next read: if err==io.EOF we still have a record, but next READ_PARA should get EOF
	// So we should not set EOF now, but remember we are at EOF for next call? Simpler: if err==io.EOF and we processed line,
	// we will set a marker that next call is EOF. Use schedEOF.
	if err == io.EOF {
		// this was last line, after this we will be at EOF
		schedEOF = true
		// But we still need to set up to mark next call as EOF; we can leave reader to return EOF next time
		// To make next call return EOF, set reader to nil after consuming? Instead keep flag
		// We'll keep schedReader but next call will see schedEOF and prior consumption?
		// Simpler: if we just processed the last line, we don't set EOF now; next call will try to read and get EOF
		// So we should not set WsEofFlag now.
		// To detect next EOF, we need to know that file is at EOF and next ReadString will return EOF with empty.
		// That's fine: we will return this record now, and next call will correctly get EOF.
		// However our current ReadString already consumed EOF; next read will be EOF again.
		// So we must not consume extra; we already set schedEOF but we can just keep reader; next call will read again.
		// For now WsEofFlag stays "N"
	} else {
		// not EOF, continue
	}

	// Parse fields from line (16 bytes)
	acct := line[0:4]
	prinField := line[4:11]  // 7 chars
	rateField := line[11:15] // 4 chars
	yearsField := line[15:16]

	prinInt := parseDigitsField(prinField)
	rateInt := parseDigitsField(rateField)

	ScAcct := acct
	ScPrin := decimal.New(prinInt, -2)
	ScRate := decimal.New(rateInt, -2)
	var scYears int64
	if len(yearsField) > 0 {
		c := yearsField[0]
		if c >= '0' && c <= '9' {
			scYears = int64(c - '0')
		} else {
			scYears = 0
		}
	}

	SchedRecCurrent = SchedRec{
		ScAcct:  ScAcct,
		ScPrin:  ScPrin,
		ScRate:  ScRate,
		ScYears: scYears,
	}
	WsEofFlag = "N"

	// If this line was the last one and we are at EOF, the next call will need to return EOF.
	// We can detect by peeking: if err==io.EOF, we keep a flag that the file is exhausted after this record.
	// But our logic above will make next READ_PARA try to read again and get EOF (since underlying file is at EOF).
	// However ReadString after EOF will return EOF immediately without data, so next call will set WsEofFlag=Y.
	// So nothing extra needed. We just need to handle the case where file had exactly one line and we read it with err==nil? Then not EOF yet.
	// The above handling for err==io.EOF already processed one record; next call will be fresh read.
	if schedEOF {
		// we have just processed the last line that came with EOF; we need to ensure next read returns EOF.
		// The underlying bufio.Reader is already at EOF, so next ReadString will return EOF empty.
		// Keep schedEOF false now to avoid confusion? Actually we want next call to go to the EOF branch.
		// Do nothing.
	}

	// Special handling for empty file: if line was empty due to immediate EOF, we already returned.
}

// PROCESS_PARA corresponds to COBOL PROCESS-PARA
func PROCESS_PARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = storeDecimal(SchedRecCurrent.ScPrin, 8, 2)

	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	for WsYear = 1; WsYear <= SchedRecCurrent.ScYears; WsYear++ {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		rateDiv := SchedRecCurrent.ScRate.Shift(-2)
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv)
		newBalRaw := WsBal.Mul(factor)
		newBalRounded := newBalRaw.Round(2)
		WsBal = storeDecimal(newBalRounded, 8, 2)

		WsBalEd = formatBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		fmt.Fprint(os.Stdout, SchedRecCurrent.ScAcct)
		fmt.Fprint(os.Stdout, " Y")
		fmt.Fprint(os.Stdout, formatPIC99(WsYear))
		fmt.Fprint(os.Stdout, " ")
		fmt.Fprint(os.Stdout, WsBalEd)
		fmt.Fprint(os.Stdout, "\n")
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Fprint(os.Stdout, SchedRecCurrent.ScAcct)
	fmt.Fprint(os.Stdout, " FINAL ")
	fmt.Fprint(os.Stdout, WsBalEd)
	fmt.Fprint(os.Stdout, "\n")
	WsCount++
	READ_PARA()
}

func MAIN_PARA() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		schedReader = nil
		WsEofFlag = "Y"
	} else {
		defer schedFile.Close()
		schedReader = bufio.NewReader(schedFile)
		READ_PARA()
		for !isInputDone() {
			PROCESS_PARA()
		}
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	fmt.Fprint(os.Stdout, "SCHEDULES: ")
	fmt.Fprint(os.Stdout, formatPIC99(WsCount))
	fmt.Fprint(os.Stdout, "\n")
}

func main() {
	MAIN_PARA()
}
